export function probeConclusive(result: StoredProbeResult): boolean {
	return !result.timedOut && !result.truncated && result.exitCode !== null && result.exitCode !== 125;
}

export function probesConclusive(tried: ProbesTried | undefined): boolean {
	return (tried?.attempts ?? []).every((id) => {
		const probe = tried?.probes?.[id];
		return probe !== undefined && probeConclusive(probe.result);
	});
}

export function runStands(
	run: LensRun,
	outcome: LensOutcome | undefined,
	refused: (key: string, model: string) => boolean,
	tried: ProbesTried | undefined,
): boolean {
	if (lensRecord(run, outcome, true, [], []).status !== "ran" || !probesConclusive(tried)) return false;
	// Only a done outcome's record reads ran.
	const done = outcome as Extract<LensOutcome, { status: "done" }>;
	return !judgedModels(done, run.probe).some((model) => refused(run.key, model));
}

// Why a level of a lens whose `extends` chain reaches the built-in `origin` may not probe, or nothing when it may.
function probeRefusal(origin: string | undefined): string | undefined {
	if (origin === undefined || !lensProbingWording.has(origin)) {
		const worded = [...lensProbingWording.keys()];
		return `"probe" needs the probing wording of a built-in lens it extends, and only the ${worded.slice(0, -1).join(", ")} and ${worded.at(-1)} lenses have it, so no lens probes under another lens's words`;
	}
	return undefined;
}

